function normAddress(v:any){return String(v??'').toLowerCase().replace(/[^a-z0-9]+/g,' ').replace(/\s+/g,' ').trim()}
async function verifiedRivetInternalOwner(req:Request,body:any){
  const sourceApp=String(req.headers.get('x-rivet-source-app')||'').trim();
  const auth=String(req.headers.get('authorization')||'').trim();
  const grant=String(req.headers.get('x-rivet-internal-grant')||'').trim();
  const reportId=String(req.headers.get('x-rivet-report-id')||'').trim();
  if(sourceApp!==RIVET_REPORTING_APP_ID)return null;
  if(!auth&&!grant)return null;
  try{
    const headers:Record<string,string>={'Content-Type':'application/json','Accept':'application/json'};
    if(auth)headers['Authorization']=auth;
    const response=await fetch(`https://base44.app/api/apps/${RIVET_REPORTING_APP_ID}/functions/verifyRivetInternalAccess`,{
      method:'POST',
      headers,
      body:JSON.stringify({
        purpose:'energy_site_lookup',
        grant,
        report_id:reportId,
        address:String(body?.address||'')
      })
    });
    const verified=await response.json().catch(()=>null);
    if(!response.ok||verified?.ok!==true||verified?.allowed!==true)return null;
    return {tier:'team',commercial_access:true,authority:String(verified?.authority||'verified_rivet_internal_owner')};
  }catch{return null;}
}
async function verifiedPaidRivetReportAccess(req:Request,me:any,body:any){
  const email=String(me?.email||'').trim().toLowerCase();
  const purchaseKey=String(req.headers.get('x-rivet-report-purchase-key')||'').trim();
  const sessionId=String(req.headers.get('x-rivet-report-session-id')||'').trim();
  const offerKey=String(req.headers.get('x-rivet-report-offer-key')||'').trim();
  if(!email||!purchaseKey||!sessionId.startsWith('cs_')||offerKey!=='rivet_report_495')return null;
  try{
    const response=await fetch(`https://base44.app/api/apps/${RIVET_PAYMENT_BROKER_APP_ID}/functions/verifyRivetCheckoutBroker`,{
      method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({stripe_session_id:sessionId,order_id:purchaseKey,offer_key:offerKey})
    });
    const verified=await response.json().catch(()=>null);
    if(!response.ok||verified?.payment_confirmed!==true)return null;
    if(String(verified?.customer_email||'').trim().toLowerCase()!==email)return null;
    if(!normAddress(verified?.requested_address)||normAddress(verified?.requested_address)!==normAddress(body?.address))return null;
    return {tier:'client',commercial_access:true,authority:'verified_rivet_report_purchase',purchase_key:purchaseKey,offer_key:offerKey};
  }catch{return null;}
}
async function resolveRivetAccess(base44:any,req:Request,me:any,body:any){
  if(me?.role==='admin')return {tier:'team',commercial_access:true,authority:'admin'};
  const email=String(me?.email||'').trim().toLowerCase();
  if(email&&RIVET_REPORTING_OWNER_EMAILS.has(email))return {tier:'team',commercial_access:true,authority:'rivet_reporting_owner'};
  const rivetInternal=await verifiedRivetInternalOwner(req,body);if(rivetInternal)return rivetInternal;
  const machineKey=Deno.env.get('SYSTEMIA_MACHINE_KEY'),supplied=req.headers.get('x-systemia-machine-key');
  if(machineKey&&supplied&&supplied===machineKey)return {tier:'team',commercial_access:true,authority:'systemia_machine'};
  const paidReportAccess=await verifiedPaidRivetReportAccess(req,me,body);if(paidReportAccess)return paidReportAccess;
  if(!email)return {tier:'free',commercial_access:false,authority:'anonymous'};
  let rows:any[]=[];try{rows=await base44.asServiceRole.entities.RIVETAccessEntitlement.filter({user_email:email},'-updated_date',50)}catch(_){rows=[]}
  const entitlement=(rows||[]).filter((r:any)=>r?.status==='active'||r?.status==='trial').sort((a:any,b:any)=>(PLAN_RANK[b?.plan]??-1)-(PLAN_RANK[a?.plan]??-1)||String(b?.updated_date||b?.created_date||'').localeCompare(String(a?.updated_date||a?.created_date||'')))[0]||null;
  const tier=entitlement?.plan==='team'?'executive':(['pro','client','partner'].includes(entitlement?.plan)?entitlement.plan:'free');
  return {tier,commercial_access:['pro','client','executive','team'].includes(tier),authority:entitlement?'entitlement':'authenticated_free'};
}
