function parseCsvText(text:string){const rows:string[][]=[];let row:string[]=[],field='',quoted=false;for(let i=0;i<text.length;i++){const ch=text[i];if(quoted){if(ch==='"'&&text[i+1]==='"'){field+='"';i++}else if(ch==='"')quoted=false;else field+=ch}else if(ch==='"')quoted=true;else if(ch===','){row.push(field);field=''}else if(ch==='\n'){row.push(field.replace(/\r$/,''));field='';if(row.some(x=>x!==''))rows.push(row);row=[]}else field+=ch}if(field||row.length){row.push(field.replace(/\r$/,''));rows.push(row)}if(!rows.length)return [];const header=rows.shift()!.map((x,i)=>i===0?x.replace(/^\uFEFF/,''):x);return rows.map(cols=>Object.fromEntries(header.map((h,i)=>[h,cols[i]??''])))}
